const MESES=["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"];
const b64=s=>{const bin=atob(s),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return u};
const fechaTexto=v=>{if(!v)return"";const[y,m,d]=v.split("-").map(Number);return d+" de "+MESES[m-1]+" de "+y};
const hoy=()=>{const t=new Date(),z=n=>String(n).padStart(2,"0");return t.getFullYear()+"-"+z(t.getMonth()+1)+"-"+z(t.getDate())};
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const q=id=>document.getElementById(id);

/* ---------- llenar la carta (el texto no cambia) ---------- */
function llenar(d){
  return LINES.map(([p,x,y,b,s,t])=>{
    let parts=[[t,0]];
    if(t.startsWith("Bogotá D.C., __")&&d.fecha) parts=[["Bogotá D.C., ",0],[d.fecha,1]];
    else if(/^_+$/.test(t)&&d.nombre) parts=[[d.nombre,1]];
    else if(t.startsWith("NIT: __")&&d.nit) parts=[["NIT: ",0],[d.nit,1]];
    else if(t==="Ciudad"&&(d.dir||d.ciudad)) parts=[[d.dir&&d.ciudad?d.dir+" – "+d.ciudad:(d.dir||d.ciudad),1]];
    else if(t.startsWith("Referencia:")&&d.caja) parts=[[t,0],[" – Estación N.° "+d.caja,1]];
    else if(t.includes("celebrado con __")&&d.nombre){const[a,c]=t.split(/_+/);parts=[[a,0],[d.nombre,1],[c,0]]}
    return{p,x,y,b,s,parts};
  });
}

/* ---------- PDF (generador propio, sin internet) ---------- */
const ESP={"€":0x80,"…":0x85,"‘":0x91,"’":0x92,"“":0x93,"”":0x94,"–":0x96,"—":0x97};
function ansi(t){const o=[];for(const ch of t){const c=ch.codePointAt(0);
  if(ESP[ch])o.push(ESP[ch]);else if((c>=32&&c<127)||(c>=160&&c<256))o.push(c);else o.push(63)}return o}
const anchoPdf=(t,b,s)=>ansi(t).reduce((a,c)=>a+MET[b?"B":"R"].w[c-32],0)*s/1000;
const hex=a=>a.map(c=>c.toString(16).padStart(2,"0")).join("");
function crearPDF(d){
  const enc=new TextEncoder(),chunks=[],offs=[];let len=0;
  const put=x=>{const u=typeof x==="string"?enc.encode(x):x;chunks.push(u);len+=u.length};
  const latin=s=>{const u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i)&255;return u};
  const obj=(n,body,stream)=>{offs[n]=len;put(n+" 0 obj\n");put(body);
    if(stream){put("\nstream\n");put(stream);put("\nendstream")}put("\nendobj\n")};
  const fR=b64(FONT_R),fB=b64(FONT_B),lg=b64(LOGO);
  const n=(d.nombre||"").replace(/[()\\]/g,"");
  const cont=[[],[]];
  for(const l of llenar(d)){const full=l.parts.map(p=>p[0]).join("");let s=l.s;const w=anchoPdf(full,l.b,s);
    if(l.x+w>MAXX)s=Math.max(6,s*(MAXX-l.x)/w);
    cont[l.p].push("BT /"+(l.b?"F2":"F1")+" "+s.toFixed(2)+" Tf 1 0 0 1 "+l.x.toFixed(3)+" "+l.y.toFixed(3)+" Tm <"+hex(ansi(full))+"> Tj ET")}
  const[lx,ly,lw,lh]=LOGO_BOX;
  const c1="q "+lw+" 0 0 "+lh+" "+lx+" "+ly+" cm /Im1 Do Q\n0 g\n"+cont[0].join("\n"),c2="0 g\n"+cont[1].join("\n");
  const fontObj=(k,name,desc)=>"<< /Type /Font /Subtype /TrueType /BaseFont /"+name+" /FirstChar 32 /LastChar 255 /Widths ["+MET[k].w.join(" ")+"] /Encoding /WinAnsiEncoding /FontDescriptor "+desc+" 0 R >>";
  const descObj=(k,name,file)=>"<< /Type /FontDescriptor /FontName /"+name+" /Flags 32 /FontBBox ["+MET[k].bbox.join(" ")+"] /ItalicAngle 0 /Ascent "+MET[k].asc+" /Descent "+MET[k].desc+" /CapHeight 729 /StemV "+(k==="B"?140:80)+" /FontFile2 "+file+" 0 R >>";
  put("%PDF-1.4\n");
  const res="<< /Font << /F1 5 0 R /F2 8 0 R >> /XObject << /Im1 11 0 R >> >>";
  obj(1,"<< /Type /Catalog /Pages 2 0 R >>");
  obj(2,"<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 >>");
  obj(3,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources "+res+" /Contents 12 0 R >>");
  obj(4,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources "+res+" /Contents 13 0 R >>");
  obj(5,fontObj("R","DejaVuSans",6));obj(6,descObj("R","DejaVuSans",7));obj(7,"<< /Length "+fR.length+" /Length1 "+fR.length+" >>",fR);
  obj(8,fontObj("B","DejaVuSans-Bold",9));obj(9,descObj("B","DejaVuSans-Bold",10));obj(10,"<< /Length "+fB.length+" /Length1 "+fB.length+" >>",fB);
  obj(11,"<< /Type /XObject /Subtype /Image /Width 225 /Height 225 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length "+lg.length+" >>",lg);
  const s1=latin(c1),s2=latin(c2);
  obj(12,"<< /Length "+s1.length+" >>",s1);obj(13,"<< /Length "+s2.length+" >>",s2);
  const tit=ansi("Terminación Acuerdo de Colaboración"+(n?" - "+n:""));
  obj(14,"<< /Title <"+hex(tit)+"> /Producer (Mi Ruta del Dia) >>");
  const x=len;let t="xref\n0 15\n0000000000 65535 f \n";for(let i=1;i<=14;i++)t+=String(offs[i]).padStart(10,"0")+" 00000 n \n";
  put(t+"trailer\n<< /Size 15 /Root 1 0 R /Info 14 0 R >>\nstartxref\n"+x+"\n%%EOF\n");
  const out=new Uint8Array(len);let o=0;for(const c of chunks){out.set(c,o);o+=c.length}return out;
}
